(()=>{
const NCHMF_RADAR="https://nchmf.gov.vn/KttvSiteE/vi-VN/1/image-ra-dar-r2.html",RAINVIEWER="https://www.rainviewer.com/map.html?loc=10.20%2C104.20%2C7&layer=radar&lm=0",NOWCAST_SOURCES=["https://raw.githubusercontent.com/kenzuko/Jotrip-Lab/data-weather/data/weather-nowcast/latest.json","/weather/nowcast.json"],REFRESH=10*60*1000;let nowcast={status:"INITIALIZING",points:{}};const $=id=>document.getElementById(id),num=v=>v===null||v===undefined||v===""||Number.isNaN(Number(v))?null:Number(v),fmt=(v,d=1)=>{v=num(v);return v===null?"—":Number(v.toFixed(d)).toString()};
function styles(){if($("observationStatusStyles"))return;const s=document.createElement("style");s.id="observationStatusStyles";s.textContent=`.observation-panel{overflow:hidden}.observation-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(290px,.65fr);gap:12px;margin-top:14px}.observation-card{border:1px solid #e2ebf1;border-radius:16px;background:linear-gradient(180deg,#fbfdfe,#f3f8fb);padding:14px;min-width:0}.observation-card header{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-bottom:8px}.observation-card h3{font-family:var(--font-display,"Manrope",sans-serif);font-size:15px;font-weight:650;margin:0;color:#123a57}.observation-card p{margin:0;color:#657b8c;font-size:10px;line-height:1.55}.observation-state{font-size:8px;font-weight:650;letter-spacing:.06em;border-radius:999px;padding:5px 8px;white-space:nowrap;background:#fff5da;color:#8d6a0b;border:1px solid #f1dca0}.observation-state.low{background:#edf8f2;color:#27744b;border-color:#cfe9da}.observation-state.watch{background:#fff8e6;color:#8a6812;border-color:#f1dfa4}.observation-state.elevated{background:#fff0dc;color:#985b16;border-color:#f2cf9d}.observation-state.high{background:#fff0f1;color:#a94249;border-color:#efc4c7}.observation-link{display:inline-flex;align-items:center;gap:6px;margin-top:10px;padding:8px 10px;border-radius:10px;background:#eaf6fd;color:#0877ad;text-decoration:none;font-size:9px;font-weight:650}.observation-note{margin-top:10px;padding-top:9px;border-top:1px solid #e8f0f5;color:#8797a2;font-size:8px;line-height:1.5}.satellite-kpi{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;margin:10px 0}.satellite-kpi div{background:#fff;border:1px solid #e4edf2;border-radius:11px;padding:8px}.satellite-kpi span{display:block;font-size:8px;color:#8696a2}.satellite-kpi b{display:block;margin-top:3px;font-family:var(--font-display,"Manrope",sans-serif);font-size:15px;font-weight:650;color:#123a57;font-variant-numeric:tabular-nums}.signal-score{font-family:var(--font-display,"Manrope",sans-serif);font-size:30px;font-weight:650;color:#123a57;line-height:1;margin:4px 0 7px}.signal-score small{font-size:10px;font-family:var(--font-ui,"Inter",sans-serif);font-weight:500;color:#7d8e99}.radar-frame{width:100%;height:360px;border:0;border-radius:13px;background:#eaf1f5;margin-top:10px}.radar-actions{display:flex;gap:8px;flex-wrap:wrap}.radar-source{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.radar-source p{max-width:620px}@media(max-width:900px){.observation-grid{grid-template-columns:1fr}.radar-frame{height:330px}}@media(max-width:640px){.radar-frame{height:300px}.radar-source{display:block}}`;document.head.appendChild(s)}
function age(){const t=Date.parse(nowcast?.sampled_time||"");if(!Number.isFinite(t))return "chưa có snapshot";const m=Math.max(0,(Date.now()-t)/60000);return m<60?`${Math.round(m)} phút trước`:`${Math.round(m/60)} giờ trước`}
function panel(){styles();if($("observationPanel"))return;const section=document.createElement("section");section.id="observationPanel";section.className="panel observation-panel";section.innerHTML=`<div class="panel-head premium-head"><div><small>NOWCAST OBSERVATION</small><h2>Radar mưa & đối lưu vệ tinh</h2></div><span id="nowcastKicker" class="section-kicker">HIMAWARI · FREE</span></div><div class="observation-grid"><article class="observation-card radar-card"><header><h3>Radar mưa trực quan</h3><span class="observation-state low">RAINVIEWER LIVE</span></header><div class="radar-source"><p>RainViewer được nhúng trực tiếp để nhìn vùng mưa và chuyển động mưa. Phủ Việt Nam bằng mạng radar tổng hợp, nhưng chất lượng có thể giảm ở vùng biển xa và nơi xa radar.</p><div class="radar-actions"><a class="observation-link" href="${RAINVIEWER}" target="_blank" rel="noopener noreferrer">Mở toàn màn hình ↗</a><a class="observation-link" href="${NCHMF_RADAR}" target="_blank" rel="noopener noreferrer">Đối chiếu NCHMF ↗</a></div></div><iframe class="radar-frame" title="RainViewer live radar around Phu Quoc" src="${RAINVIEWER}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><div class="observation-note">RainViewer là lớp quan sát trực quan, không phải dependency của Weather/Marine backend và không tự phát GO/HOLD. NCHMF vẫn được giữ làm nguồn đối chiếu chính thức khi cần xác nhận.</div></article><article class="observation-card"><header><h3>Tín hiệu đối lưu</h3><span id="convectiveState" class="observation-state">ĐANG KHỞI TẠO</span></header><div id="convectiveScore" class="signal-score">— <small>/100</small></div><p id="convectiveText">Đang đọc quan sát mây từ Himawari-9.</p><div class="satellite-kpi"><div><span>Nhiệt độ mây p05</span><b id="cloudTemp">—</b></div><div><span>Độ cao mây p95</span><b id="cloudHeight">—</b></div><div><span>Làm lạnh ~20 phút</span><b id="cloudCooling">—</b></div><div><span>Tuổi dữ liệu</span><b id="satAge">—</b></div></div><div class="observation-note">Dữ liệu mây là quan sát thật từ JMA Himawari-9 qua NOAA Open Data, cửa sổ cục bộ khoảng 40 km. Chỉ số 0–100 là tín hiệu đối lưu suy ra từ nhiệt độ, độ cao và cooling đỉnh mây.</div></article></div>`;const tide=$("tidePanel"),aq=$("airQualityPanel"),conditions=document.querySelector(".conditions");(tide||aq||conditions)?.insertAdjacentElement("afterend",section)}
function render(){panel();const key=window.currentPoint||(typeof currentPoint!=="undefined"?currentPoint:"");const p=nowcast?.points?.[key]||{},sig=p.convective_signal||{},level=String(sig.level||"PENDING").toUpperCase();const badge=$("convectiveState");if(badge){badge.textContent=level==="PENDING"?"CHƯA CÓ DỮ LIỆU":level;badge.className=`observation-state ${level.toLowerCase()}`};$("convectiveScore").innerHTML=`${sig.score??"—"} <small>/100</small>`;const cloudTemp=p.regional_cold_cloud_top_temp_c??p.regional_min_cloud_top_temp_c,cloudHeight=p.regional_high_cloud_top_height_m??p.regional_max_cloud_top_height_m;$("cloudTemp").textContent=num(cloudTemp)!==null?`${fmt(cloudTemp,1)} °C`:"—";$("cloudHeight").textContent=num(cloudHeight)!==null?`${fmt(cloudHeight/1000,1)} km`:"—";$("cloudCooling").textContent=num(p.cooling_c_per_20m_proxy)!==null?`${fmt(p.cooling_c_per_20m_proxy,1)} °C`:"—";$("satAge").textContent=age();const messages={LOW:"Chưa thấy tín hiệu đối lưu sâu đáng kể trong vùng cục bộ.",WATCH:"Có dấu hiệu mây đối lưu đang phát triển. Theo dõi radar và cập nhật tiếp theo.",ELEVATED:"Tín hiệu đối lưu sâu rõ hơn. Cần tăng mức theo dõi radar và diễn biến mây.",HIGH:"Tín hiệu đối lưu vệ tinh mạnh, cần theo dõi sát radar và diễn biến thực tế."};$("convectiveText").textContent=messages[level]||"Chưa có snapshot Himawari hợp lệ.";if($("nowcastKicker"))$("nowcastKicker").textContent=nowcast?.status==="POINT_NUMERIC_READY"?"HIMAWARI · OBSERVED":"HIMAWARI · PENDING"}
async function loadNowcast(){let lastError=null,loaded=false;for(const url of NOWCAST_SOURCES){try{const sep=url.includes("?")?"&":"?",r=await fetch(`${url}${sep}t=${Date.now()}`,{cache:"no-store"});if(!r.ok)throw new Error(`${url} HTTP ${r.status}`);const data=await r.json();if(data?.status!=="POINT_NUMERIC_READY"||!data?.points)throw new Error(`${url} invalid nowcast payload`);nowcast={...nowcast,...data,points:data.points};loaded=true;break}catch(e){lastError=e}}if(!loaded)nowcast={...nowcast,status:"UNAVAILABLE",detail:lastError?.message||"Nowcast unavailable"};render()}
function cleanLegacy(){document.querySelectorAll("#sources .source").forEach(el=>{const name=el.querySelector("b")?.textContent?.trim();if(name!=="RADAR_LIGHTNING")return;const state=el.querySelector(".state"),span=el.querySelector("span");if(state){state.textContent="SEPARATE LAYER";state.className="state partial"}if(span){const br=span.querySelector("br");if(br){while(br.nextSibling)br.nextSibling.remove();br.after(document.createTextNode("Nowcast tách khỏi backend dự báo: RainViewer live radar + NCHMF đối chiếu + Himawari observed."))}}});document.querySelectorAll("#gaps .gap").forEach(el=>{const name=el.querySelector("b")?.textContent?.trim(),span=el.querySelector("span");if(name==="Nowcast offshore"&&span)span.textContent="Đã có Himawari observed và RainViewer live radar làm lớp trực quan độc lập. Coverage radar ngoài khơi vẫn có thể biến thiên nên cần đối chiếu nguồn chính thức khi cần.";if(name==="Hmax trực tiếp"&&span&&/ValueError|Cannot find index entries/i.test(span.textContent||""))span.textContent="ECMWF Open Data không phát hành trực tiếp Hmax. Dashboard dùng Hmax ước tính Rayleigh 20 phút từ Hs và công khai phương pháp."})}
function install(){panel();cleanLegacy();loadNowcast();document.querySelectorAll(".point-tabs button").forEach(btn=>btn.addEventListener("click",()=>setTimeout(render,0)));const roots=[$("sources"),$("gaps")].filter(Boolean),observer=new MutationObserver(()=>cleanLegacy());roots.forEach(r=>observer.observe(r,{childList:true,subtree:true}));setInterval(loadNowcast,REFRESH)}
window.WeatherLabObservationStatus={install,render,loadNowcast};
})();